    private void createService() {
        final UserAdmin userAdmin = mock(UserAdmin.class);
        when(userAdmin.getRole(anyString())).thenAnswer(i -> this.roles.get(i.getArgument(0, String.class)));
        when(userAdmin.createRole(anyString(), anyInt())).thenAnswer(i -> this.roles.get(i.getArgument(0, String.class)));

        final EnvironmentInfo environmentInfo = mock(EnvironmentInfo.class);
        when(environmentInfo.getNonFrameworkArgs()).thenReturn(this.frameworkCommandLineArguments);

        this.service = new ConfigurationRestService();
        this.service.setEnvironmentInfo(environmentInfo);
        this.service.setUserAdmin(userAdmin);
        this.service.setCryptoService(mock(CryptoService.class));
        this.service.setConfigurationService(this.configurationService);
    }
